   ("γεμίζω", "γέμισα", "γέμισε / γεμίστε", "fill, stuff"), ("τυλίγω", "τύλιξα", "τύλιξε / τυλίξτε", "wrap, roll up"), ("μαρινάρω", "μαρινάρισα", "μαρινάρισε / μαρινάρετε", "marinate"),
   ("μουλιάζω", "μούλιασα", "μούλιασε / μουλιάστε", "soak"), ("στραγγίζω", "στράγγισα", "στράγγισε / στραγγίστε", "drain, strain"), ("αλατίζω", "αλάτισα", "αλάτισε / αλατίστε", "salt"),
