   ("ψήνω", "έψησα", "ψήσε / ψήστε", "bake, roast, grill"), ("μαγειρεύω", "μαγείρεψα", "μαγείρεψε / μαγειρέψτε", "cook"), ("ζεσταίνω", "ζέστανα", "ζέστανε / ζεστάνετε", "heat"),
   ("ρίχνω", "έριξα", "ρίξε / ρίξτε", "add, pour in"), ("βάζω", "έβαλα", "βάλε / βάλτε", "put"), ("προσθέτω", "πρόσθεσα", "πρόσθεσε / προσθέστε", "add"),
   ("αφήνω", "άφησα", "άφησε (άσε) / αφήστε", "leave, let"), ("σκεπάζω", "σκέπασα", "σκέπασε / σκεπάστε", "cover"), ("χαμηλώνω", "χαμήλωσα", "χαμήλωσε / χαμηλώστε", "lower (the heat)"),
