 grammar=[
  dict(level="B1", title="Imperative from the aorist stem: έκοψα → κόψε, κόψτε",
       el="Η στιγμιαία προστακτική φτιάχνεται από το θέμα του αορίστου: έκοψα → κόψ- → κόψε (ενικός), κόψτε (πληθυντικός).",
       en="Take the aorist, drop the augment and ending to get the stem, then add **-ε** (singular) or **-τε** (plural): *έκοψα → κοψ- → κόψε, κόψτε*; *έβρασα → βρασ- → βράσε, βράστε*. In the singular the stress goes back as far as it can (*ανακάτεψε, πασπάλισε*); in the plural it falls on the second-last syllable (*ανακατέψτε, πασπαλίστε*). After a stem in a vowel or -ν- the plural is **-ετε**: *πλύνετε, ζεστάνετε*. Verbs in **-άρω** from French or Italian keep the present stem in the plural: *σοτάρετε, σερβίρετε, μαρινάρετε*.",
       examples=[("Ψιλοκόψτε το κρεμμύδι.", "Finely chop the onion."), ("Ανακατέψτε καλά.", "Stir well."), ("Σερβίρετε ζεστό.", "Serve hot.")]),
  dict(level="B1+", title="Imperfective imperative for continuous actions: ανακατεύετε συνέχεια",
       el="Όταν μια ενέργεια κρατάει ή επαναλαμβάνεται, η συνταγή χρησιμοποιεί την εξακολουθητική προστακτική: «ανακατεύετε συνέχεια».",
       en="Greek has a second, **imperfective** imperative, built on the present stem (*ανακάτευε / ανακατεύετε*). Recipes use it for actions that go on or repeat: *ανακατεύετε συνέχεια* (keep stirring), *χτυπάτε μέχρι να αφρατέψει* (keep beating until fluffy), *ρίχνετε το γάλα σιγά σιγά* (pour the milk in gradually). The perfective (*ανακατέψτε*) is for one complete action: *ανακατέψτε και σερβίρετε*.",
       examples=[("Ανακατεύετε συνέχεια για να μην κολλήσει.", "Keep stirring so it doesn't stick."), ("Ρίχνετε το γάλα λίγο λίγο.", "Add the milk a little at a time.")]),
  dict(level="B1+", title="Prefixes that change the meaning: ψιλο-, σιγο-, ξε-",
       el="Τα προθέματα ψιλο- (λεπτά), σιγο- (σιγά) και ξε- (αφαίρεση) φτιάχνουν νέα ρήματα: ψιλοκόβω, σιγοβράζω, ξεφλουδίζω.",
       en="**ψιλο-** “finely”: *ψιλοκόβω* (chop finely). **σιγο-** “slowly, gently”: *σιγοβράζω* (simmer), *σιγοψήνω* (cook slowly). **ξε-** removes or reverses: *ξεφλουδίζω* (peel: remove the skin), *ξεπαγώνω* (defrost: un-freeze), *ξεκοκαλίζω* (bone: remove the bones), *ξεπλένω* (rinse).",
       examples=[("Ξεπαγώστε το χταπόδι από το βράδυ.", "Defrost the octopus the night before."), ("Σιγοβράστε για μία ώρα.", "Simmer for an hour.")]),
 ],
