 grammar=[
  dict(level="B2", title="μέχρι να, μόλις, αφού + perfective subjunctive",
       el="Μετά από «μέχρι να», «μόλις» και «αφού», όταν μιλάμε για το μέλλον, βάζουμε το ρήμα στη στιγμιαία μορφή: «μέχρι να βράσει», «μόλις βράσει», «αφού βράσει».",
       en="These conjunctions refer to a change that will be complete, so they take the **perfective** (aorist-stem) form: *μέχρι να βράσει* (until it boils), *μόλις κρυώσει* (as soon as it cools), *αφού ροδίσει* (once it has browned). *Μέχρι να* needs *να*; *μόλις* and *αφού* do not. Compare the imperfective for an ongoing process: *όσο βράζει, ετοιμάστε τη σάλτσα* (while it boils, prepare the sauce).",
       examples=[("Σοτάρετε μέχρι να μαλακώσουν τα κρεμμύδια.", "Sauté until the onions soften."), ("Μόλις πάρει βράση, ρίξτε το ρύζι.", "As soon as it boils, add the rice."), ("Όσο βράζουν οι πατάτες, κόψτε την ντομάτα.", "While the potatoes boil, cut the tomato.")]),
  dict(level="B2", title="Purpose and prevention: για να, να μην",
       el="Για τον σκοπό λέμε «για να» + υποτακτική· για κάτι που θέλουμε να αποφύγουμε, «για να μην» ή απλώς «να μην».",
       en="Purpose: **για να** + subjunctive: *σκεπάστε για να μη χάσει τα υγρά του* (cover so it doesn't lose its moisture). Prevention alone: **να μην** + subjunctive: *ανακατεύετε να μην κολλήσει*. Note *μη* before most consonants and *μην* before vowels and κ, π, τ, ξ, ψ, μπ, ντ, γκ, τσ, τζ: *να μη σκάσει*, but *να μην κολλήσει*.",
       examples=[("Τρυπήστε τα λουκάνικα να μη σκάσουν.", "Prick the sausages so they don't burst."), ("Λαδώστε το ταψί για να μην κολλήσει η πίτα.", "Grease the tin so the pie doesn't stick.")]),
  dict(level="B2", title="The mediopassive in recipes: σερβίρεται, κόβεται, διατηρείται",
       el="Το παθητικό σε -εται/-ονται περιγράφει τι γίνεται με το φαγητό χωρίς να λέει ποιος το κάνει.",
       en="The 3rd-person mediopassive in **-εται / -ονται** describes what is done to the food without naming the cook: *το φαγητό σερβίρεται με φέτα* (the dish is served with feta), *τα ρεβίθια μουλιάζονται από το βράδυ* (the chickpeas are soaked overnight). It is typical of older cookbooks and of notes at the end of recipes: *διατηρείται τρεις μέρες στο ψυγείο* (keeps three days in the fridge).",
       examples=[("Η σαλάτα σερβίρεται αμέσως.", "The salad is served at once."), ("Η σούπα διατηρείται δύο μέρες.", "The soup keeps for two days.")]),
 ],
